def semver_sort(versions):
    def parse(v):
        core = v
        pre = None
        if '+' in core:
            core = core.split('+', 1)[0]
        if '-' in core:
            core, pre = core.split('-', 1)
        major, minor, patch = (int(x) for x in core.split('.'))
        pre_ids = pre.split('.') if pre is not None else None
        return (major, minor, patch, pre_ids)

    def pre_key(pre_ids):
        if pre_ids is None:
            return (1,)  # no prerelease sorts after
        key = [0]
        for ident in pre_ids:
            if ident.isdigit():
                key.append((0, int(ident)))
            else:
                key.append((1, ident))
        return (0, tuple(key[1:]), len(pre_ids))

    def full_key(v):
        major, minor, patch, pre_ids = parse(v)
        return (major, minor, patch, pre_key(pre_ids))

    return sorted(versions, key=full_key)

